  int count = 0;
  for (int i = 0; i < n; i++)
    if (i % 11 == 0 || i % 13 == 0) {
      int q = i;
      while (q > 0) {
        if (q % 10 == 7) count += 1;
        q = q / 10;}}
  return count;}
```
```
Pseudocode
long long sub_12F0(int a1) {
  unsigned int v1;
  unsigned int v2;
  unsigned int v3;
  v1 = 0;
  v2 = 0;
  if (a1 > 0) {
    while (a1 != ++v1) {
      while (-1171354717 * v1 <= 390451572 || -991146299 * v1 <= 330382099) {
        v3 = v1;
        do {
          v2 += v3 % 10 == 7;
          v3 /= 10u;
        } while (v3);
        if (a1 == ++v1) return v2;}}}
  return v2;}
